// ---------------------------------------------------------------- renderers
void oled_render_layer_state(void) {
    // oled_write_raw_P / oled_write_ln skip unchanged bytes, so it is fine to
    // redraw every task cycle - this also repaints correctly after the OLED
    // wakes from its idle timeout.
    const char *icon;
    switch (get_highest_layer(layer_state)) {
        case 1:  icon = oled_icon_nav;  break;
        case 2:  icon = oled_icon_sym;  break;
        case 3:  icon = oled_icon_fn;   break;
        default: icon = oled_icon_base; break;
    }
    oled_set_cursor(0, 0);
    oled_write_raw_P(icon, OLED_ICON_BYTES);

    oled_set_cursor(0, 3);  // page 3 = bottom 8 px
    oled_write_ln(read_layer_state(), false);
}

void oled_render_anim(void) {
    static uint32_t anim_timer = 0;
    static uint8_t  frame      = 0;

    if (timer_elapsed32(anim_timer) > OLED_ANIM_FRAME_DURATION) {
        anim_timer = timer_read32();
        frame      = (frame + 1) % OLED_ANIM_FRAMES;
    }
    // Redraw every cycle (unchanged bytes are skipped by the driver) so the
    // frame is repainted after the OLED wakes from its idle timeout.
    oled_set_cursor(0, 0);
    oled_write_raw_P(oled_anim_frames[frame], sizeof(oled_anim_frames[0]));
}

